class Solution {
public:
    int k, ans = 0;
    pair<vector<int>, int> dfs(TreeNode* node) {
        if (!node) return {{}, 0};
        auto [lv, ls] = dfs(node->left);
        auto [rv, rs] = dfs(node->right);
        vector<int> vals = lv;
        vals.insert(vals.end(), rv.begin(), rv.end());
        vals.push_back(node->val);
        sort(vals.begin(), vals.end());
        if ((int)vals.size() > k) vals.resize(k);
        int size = ls + rs + 1;
        if (size >= k && (int)vals.size() >= k && vals[k-1] < node->val) ans++;
        return {vals, size};
    }
    int countGreatEnoughNodes(TreeNode* root, int k) {
        this->k = k;
        dfs(root);
        return ans;
    }
};

