class Solution {
    private int k, ans;
    private int[] dfs(TreeNode node) {
        if (node == null) return new int[0];
        int[] a = dfs(node.left), b = dfs(node.right);
        int[] vals = new int[a.length + b.length + 1];
        System.arraycopy(a, 0, vals, 0, a.length);
        System.arraycopy(b, 0, vals, a.length, b.length);
        vals[vals.length - 1] = node.val;
        Arrays.sort(vals);
        int len = Math.min(k, vals.length);
        int[] res = Arrays.copyOf(vals, len);
        if (len >= k && res[k-1] < node.val) ans++;
        return res;
    }
    public int countGreatEnoughNodes(TreeNode root, int k) {
        this.k = k;
        dfs(root);
        return ans;
    }
}

