class Solution:
    def countGreatEnoughNodes(self, root: Optional[TreeNode], k: int) -> int:
        self.k = k
        self.ans = 0
        def dfs(node):
            if not node:
                return [], 0
            lv, ls = dfs(node.left)
            rv, rs = dfs(node.right)
            size = ls + rs + 1
            if size >= k:
                smaller = sum(v < node.val for v in lv) + sum(v < node.val for v in rv)
                if smaller >= k:
                    self.ans += 1
            vals = sorted(lv + rv + [node.val])[:k]
            return vals, size
        dfs(root)
        return self.ans

