class Solution {
    private int k, ans;
    private int[][] dfs(TreeNode node) {
        if (node == null) return new int[][]{new int[0], {0}};
        int[][] L = dfs(node.left), R = dfs(node.right);
        int[] lv = L[0], rv = R[0];
        int size = L[1][0] + R[1][0] + 1;
        if (size >= k) {
            int smaller = 0;
            for (int v : lv) if (v < node.val) smaller++;
            for (int v : rv) if (v < node.val) smaller++;
            if (smaller >= k) ans++;
        }
        int[] vals = new int[lv.length + rv.length + 1];
        System.arraycopy(lv, 0, vals, 0, lv.length);
        System.arraycopy(rv, 0, vals, lv.length, rv.length);
        vals[vals.length - 1] = node.val;
        Arrays.sort(vals);
        int[] res = Arrays.copyOf(vals, Math.min(k, vals.length));
        return new int[][]{res, {size}};
    }
    public int countGreatEnoughNodes(TreeNode root, int k) {
        this.k = k;
        dfs(root);
        return ans;
    }
}

